return {rwnpc01={id="rwnpc01",baseId="rwnpc01",combatid={1,1001},name="白衣女子",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL白衣女子：我的孩子……进了前面的村子就不见了，我过不了河，可否请少侠替我进村寻找。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"CYN白衣女子仍低着头，只抬起一只手臂，将一个小小的银镯子交与你。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL白衣女子：我的孩子唤作殷桃，脚上带着银镯，与我手中这镯子为一对。NOR"}},{type="itemin",args={"23zyrwitem01",1}},{type="tips",args={"获得银镯子*1"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="gaintab",args={"39001",2}},{type="refresh",args={}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="redoc",args={"YEL白衣女子：我夫君去的早，只余我们母女相依为命……NOR","YEL白衣女子：拜托少侠了，若少侠能帮我找寻回殷桃，拿我的全部身家性命答谢少侠又有何妨？NOR"}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},rwnpc02={id="rwnpc02",baseId="rwnpc02",combatid={1,1001},name="乔同山",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL乔同山：哎哟，山神保佑，方才你若是慢上一步，恐怕就被山洪冲走了。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL乔同山：看你是外乡人，大老远来我们这个荒村做什么？不过，不管你做什么都不用急了，在